// This is a fail-closed stub. The supplied demo Orders POST is not a payment
// status endpoint. Configure a documented status API and live-test it FIRST.
const b=$input.first().json.body??{};
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if(b.agentKey!=='ancfz'||typeof b.ticketId!=='string'||!uuid.test(b.ticketId)) throw new Error('Invalid ANCFZ scope');
if(typeof b.orderReference!=='string'||!b.orderReference.trim()||b.orderReference.length>200) throw new Error('Missing provider order reference');
if(typeof b.externalReference!=='string'||!/^ANCFZ-[A-Za-z0-9_-]{8,160}$/.test(b.externalReference)) throw new Error('Invalid authorized order correlation');
if(b.currency!=='AED'||typeof b.amount!=='string'||!/^(?:0|[1-9]\d{0,7})\.\d{2}$/.test(b.amount)) throw new Error('Invalid expected payment');
return [{json:{ticketId:b.ticketId,orderReference:b.orderReference,externalReference:b.externalReference,amount:b.amount,currency:'AED'}}];

// Never infer payment from customer claims, order creation or a guessed GET.
// The operator must add a documented Demo Orders GET/status endpoint,
// verify returned provider ID, amount, currency and a terminal paid state,
// and independently validate it in Node before issuing an invoice.
const expected=$('Validate Verification Request').first().json;
return [{json:{status:'verification_unconfigured',verified:false,provider:'mockgateway_demo_orders',orderReference:expected.orderReference,ticketId:expected.ticketId,amount:expected.amount,currency:expected.currency}}];
